package gt.com.ro.devumgapp.notificacion;
import android.content.Context; import com.google.firebase.messaging.FirebaseMessaging; import gt.com.ro.devumgapp.core.network.RetrofitClient; import gt.com.ro.devumgapp.core.session.SessionManager; import retrofit2.*;
public final class PushRegistrationManager { private PushRegistrationManager(){} private static NotificationApi api(){return RetrofitClient.getClient().create(NotificationApi.class);} public static void register(Context c){if(!SessionManager.getInstance().isLoggedIn())return;FirebaseMessaging.getInstance().getToken().addOnSuccessListener(token->{NotificationModels.Device d=new NotificationModels.Device();d.token=token;api().register(d).enqueue(new Callback<Void>(){public void onResponse(Call<Void>x,Response<Void>r){}public void onFailure(Call<Void>x,Throwable t){}});});} public static void unregister(Context c,Runnable done){FirebaseMessaging.getInstance().getToken().addOnSuccessListener(token->api().unregister(token).enqueue(new Callback<Void>(){public void onResponse(Call<Void>x,Response<Void>r){done.run();}public void onFailure(Call<Void>x,Throwable t){done.run();}})).addOnFailureListener(e->done.run());} }
